  "schema_version": 5,
  "type": "refactor",
  "problem": [
    {
      "text": "LinearEXL3 declared config as Config even though its constructor never reads or stores that argument.",
      "basis": "source",
      "evidence": ["call_62aca3bcbdb4496a84d02899a1e99db2"]
    }
  ],
  "reasoning": [
    {
      "text": "The cleanup changes only the annotation to Config | None, making the declared interface agree with the argument's unused status rather than removing a positional parameter.",
      "basis": "source",
      "evidence": ["call_cbb9f1ebb5714e2496f7d3636700178d", "call_62aca3bcbdb4496a84d02899a1e99db2"]
    }
  ],
  "impact": [
    {
      "text": "None becomes explicitly permitted by the annotation, but config remains required: no default is added. Tensor validation, initialization and inference code are unchanged.",
      "basis": "source",
      "evidence": ["call_cbb9f1ebb5714e2496f7d3636700178d"]
    }
  ],
  "source_notes": [
    {
      "text": "Closed issue #11, “AssertionError: bias is wrong datatype,” reports a conversion failure and subsequent successful fix. Its connection here is inferred solely from its traceback naming LinearEXL3.__init__; this annotation-only change does not alter bias handling.",
      "basis": "inference",
      "evidence": ["call_f8dbdcf93b9740ed9f045d89f7254008", "call_cbb9f1ebb5714e2496f7d3636700178d"]
    }
  ],
  "limitations": [
    "No repository execution or type-checker validation was performed. This annotation-only change offers no useful numerical computation to validate.",
    "Literal whole-tree searches establish the named construction sites, not dynamic or external callers."
  ],
  "links": ["543c4b27714c6a677a6e714c452d62532f634cff"],
  "chapters": [
    {
      "id": "quantized-inference",
      "title": "Declare nullable configuration without changing construction",
      "claims": [
        {
          "text": "LinearEXL3.__init__ changes config: Config to config: Config | None. The constructor does not dereference config or assign self.config; its state comes from dimensions, quantization tensors, bias and output dtype. Accepting None therefore requires no new runtime branch.",
          "basis": "source",
          "evidence": ["call_cbb9f1ebb5714e2496f7d3636700178d", "call_62aca3bcbdb4496a84d02899a1e99db2"]
        },
        {
          "text": "Whole-parent-tree search finds two direct construction sites, both in Linear: load_exl3 passes self.config with loaded tensors, and convert_exl3 passes self.config with quantizer outputs and the original bias. Both remain compatible; neither is changed to pass None. Other matches are imports, the class definition and an isinstance check, not additional constructors or subclasses.",
          "basis": "source",
          "evidence": ["call_7b9e2a29e47d4567a5198b3f2638c6d9", "call_64916931b83640f086c26f87cee60f7c"]
        },
        {
          "text": "Retaining the argument preserves those positional calls while relaxing the declared type. This is interface cleanup, not evidence of a new configuration-free loading workflow: Linear.load_exl3 still reads checkpoint tensors through self.config.stc before construction.",
          "basis": "inference",
          "evidence": ["call_cbb9f1ebb5714e2496f7d3636700178d", "call_64916931b83640f086c26f87cee60f7c"]
        },
        {
          "text": "The earlier quantized-inference entry establishes the loading/reconstruction interface and records incomplete packed-sign support in its historical implementation.",
          "basis": "ancestor",
          "evidence": ["call_b9e5981c7fe74f8c9074916f04c0783b"]
        },
        {
          "text": "That historical Python packed-sign concern is changed in the inspected parent: construction unpacks supplied su/sv into suh/svh and stores su/sv as None, so forward receives unpacked factors and get_weight_tensor avoids truth-testing stored packed tensors. The task leaves this initialization unchanged; this inspection does not validate GPU execution.",
          "basis": "source",
          "evidence": ["call_62aca3bcbdb4496a84d02899a1e99db2", "call_cbb9f1ebb5714e2496f7d3636700178d"]
        }
      ]
    }
  ],
  "findings": [],
  "summary": "Makes LinearEXL3's unused config argument explicitly nullable without changing its required position, callers or runtime computation."
}
